package com.salespunch360.mobile
import android.app.Application;import androidx.lifecycle.AndroidViewModel;import androidx.lifecycle.viewModelScope;import com.salespunch360.mobile.account.*;import com.salespunch360.mobile.data.*;import java.io.IOException;import java.util.UUID;import kotlinx.coroutines.flow.MutableStateFlow;import kotlinx.coroutines.flow.StateFlow;import kotlinx.coroutines.launch;import kotlinx.serialization.json.*
data class PayableBill(val id:String,val branchId:String,val vendorId:String,val number:String,val outstanding:String);data class VendorPaymentRow(val id:String,val number:String,val date:String,val amount:String,val mode:String);data class VendorPaymentState(val loading:Boolean=true,val saving:Boolean=false,val branches:List<SalesOption> = emptyList(),val vendors:List<SalesOption> = emptyList(),val accounts:List<SalesOption> = emptyList(),val bills:List<PayableBill> = emptyList(),val history:List<VendorPaymentRow> = emptyList(),val branchId:String="",val vendorId:String="",val billId:String="",val amount:String="",val date:String=java.time.LocalDate.now().toString(),val mode:String="BANK",val accountId:String="",val reference:String="",val notes:String="",val error:String?=null,val message:String?=null)
class VendorPaymentViewModel(app:Application):AndroidViewModel(app){private val api=ApiClient(SecureSession(app));private val _state=MutableStateFlow(VendorPaymentState());val state:StateFlow<VendorPaymentState> = _state;init{refresh()};fun update(f:(VendorPaymentState)->VendorPaymentState){_state.value=f(_state.value)};fun refresh()=viewModelScope.launch{update{it.copy(loading=true,error=null)};try{val x=api.vendorPaymentContext(),branches=x.array("branches").map{it.option()};update{it.copy(loading=false,branches=branches,vendors=x.array("vendors").map{v->v.option()},accounts=x.array("moneyAccounts").map{a->a.option()},bills=x.array("documents").map{b->PayableBill(b.str("id"),b.str("branchId"),b.str("vendorId"),b.str("documentNumber"),b.str("outstanding"))},history=x.array("payments").map{p->VendorPaymentRow(p.str("id"),p.str("settlementNumber"),p.str("transactionDate").take(10),p.str("amount"),p.str("paymentMode"))},branchId=it.branchId.ifBlank{branches.firstOrNull()?.id.orEmpty()})}}catch(e:Exception){fail(e)}};fun save()=viewModelScope.launch{val s=_state.value;if(s.amount.toDoubleOrNull()?.let{it>0}!=true||s.billId.isBlank()){update{it.copy(error="Select a bill and enter a positive amount.")};return@launch};update{it.copy(saving=true)};try{api.createVendorPayment(buildJsonObject{put("idempotencyKey",UUID.randomUUID().toString());put("type","VENDOR_PAYMENT");put("branchId",s.branchId);put("partyId",s.vendorId);put("paymentMode",s.mode);s.accountId.takeIf{it.isNotBlank()}?.let{put("moneyAccountId",it)};put("amount",s.amount);put("transactionDate",s.date);put("reference",s.reference);put("notes",s.notes);putJsonArray("allocations"){add(buildJsonObject{put("documentId",s.billId);put("amount",s.amount)})}});update{it.copy(saving=false,billId="",amount="",message="Vendor payment posted by the server.")};refresh()}catch(e:Exception){fail(e)}};private fun fail(e:Exception){update{it.copy(loading=false,saving=false,error=if(e is IOException)"You're offline. The payment was not posted." else "The server rejected this vendor payment.")}}}
